package com.campusiq.platform.strategy; import com.campusiq.platform.entity.Platform; import org.springframework.stereotype.Component; import java.util.*; @Component public class PlatformStrategyFactory {private final Map<Platform,PlatformProfileStrategy> strategies; public PlatformStrategyFactory(List<PlatformProfileStrategy> list){strategies=list.stream().collect(java.util.stream.Collectors.toMap(PlatformProfileStrategy::getPlatform,s->s));} public PlatformProfileStrategy get(Platform p){return Optional.ofNullable(strategies.get(p)).orElseThrow(()->new IllegalArgumentException("Unsupported platform"));}}
